# v101: az Anio Novus travertin-alapú, mért hozama a Frontinus-adatok mellé
def build(l):
    H=l=='hu'
    T=lambda h,e:h if H else e
    rows=[
     (T('Galleria Egidio (Tivoli-hurok, föld alatt)','Galleria Egidio (Tivoli Loop, underground)'),T('korai','early'),T('0,93 ± 0,15','0.93 ± 0.15'),T('1,1 ± 0,1','1.1 ± 0.1'),T('0,81','0.81')),
     (T('Empiglione-híd (tivoli elkerülő ág)','Empiglione Bridge (Tivoli Bypass)'),T('utolsó','latest'),T('1,6 ± 0,2','1.6 ± 0.2'),T('1,9','1.9'),T('0,88','0.88')),
     (T('Roma Vecchia (ívsor a város előtt)','Roma Vecchia (arcade outside the city)'),T('utolsó','latest'),T('1,2 (+0,4/−0,5)','1.2 (+0.4/−0.5)'),T('1,4 ± 0,4','1.4 ± 0.4'),T('1,0','1.0'))]
    o=[]
    o.append('      <h4 class="aqh4">'+T('Mért hozam: az Anio Novus','A measured flow: the Anio Novus')+'</h4>')
    o.append('      <p class="hint">'+T('Frontinus csak a víz keresztmetszetét mérte, a sebességét nem, ezért számaiból nem lehet térfogatáramot számolni. Az Anio Novus az egyetlen vezeték, amelynek valódi hozamát modern mérés alapján megbecsülték: a csatorna falán és alján lerakódott mészkő (travertin) megőrizte, meddig ért a víz, a felszínén kialakult hullámmintázat pedig azt, milyen gyorsan folyt. Három helyen mértek: kettő Tivoli környékén van, a harmadik közvetlenül Róma előtt.','Frontinus measured only the cross-section of the water, not its velocity, so his figures cannot be turned into a flow rate. The Anio Novus is the only aqueduct whose actual flow has been estimated from modern measurements: the limestone (travertine) deposited on the walls and floor of the channel preserved the level the water reached, and the ripple pattern on its surface how fast it flowed. Measurements were taken at three sites: two near Tivoli, the third just outside Rome.')+'</p>')
    o.append('      <div class="regwrap"><table class="regtab aniotab">')
    o.append('        <thead><tr><th>'+T('Mérési hely','Site')+'</th><th>'+T('Állapot','State')+'</th><th>'+T('Hozam a hullámmintázatból (m³/s)','Flow from the ripples (m³/s)')+'</th><th>'+T('Hozam a csatorna alakjából (m³/s)','Flow from channel geometry (m³/s)')+'</th><th>'+T('Sebesség (m/s)','Velocity (m/s)')+'</th></tr></thead>')
    o.append('        <tbody>')
    for r in rows: o.append('          <tr><td>'+r[0]+'</td><td>'+r[1]+'</td><td><b>'+r[2]+'</b></td><td>'+r[3]+'</td><td>'+r[4]+'</td></tr>')
    o.append('        </tbody>')
    o.append('      </table></div>')
    o.append('      <p class="hint aqleg">'+T('A „korai” és az „utolsó” a szerzők megnevezése: a lerakódás egy korai, illetve a legkésőbbi felszínéhez tartozó áramlás; évszámot nem adnak hozzá. A bizonytalanság két szórásnyi; az Empiglione-hídnál a csatorna alakjából számolt értékhez a szerzők nem tudtak bizonytalanságot adni. A sebesség a hullámmintázatból számolt keresztmetszeti átlag.','“Early” and “latest” are the authors’ labels: the flow belonging to an early and to the last surface of the deposit; they give no dates for them. Uncertainties are two standard deviations; for the geometry-based value at Empiglione Bridge the authors could not give one. Velocity is the cross-sectional mean calculated from the ripples.')+'</p>')
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+T('Keenan-Jones és társai, <i>Scientific Reports</i> 12 (2022) 1239, S3. kiegészítő táblázat (CC BY 4.0); a Roma Vecchia-i 1,4 ± 0,4 m³/s eredetileg: Keenan-Jones, Motta, Garcia, Fouke, <i>Journal of Archaeological Science: Reports</i> 3 (2015) 1–10.','Keenan-Jones et al., <i>Scientific Reports</i> 12 (2022) 1239, Supplementary Table S3 (CC BY 4.0); the 1.4 ± 0.4 m³/s at Roma Vecchia first in Keenan-Jones, Motta, Garcia, Fouke, <i>Journal of Archaeological Science: Reports</i> 3 (2015) 1–10.')+'</p>')
    o.append('      <p class="hint">'+T('A Rómába érkező víz tehát a vezeték kései állapotában másodpercenként 1,2–1,4 m³ volt; az 1,4 m³/s napi 120 960 ± 34 560 m³-nek felel meg. A csatorna szűkületei miatt 2 m³/s-nál több sosem folyhatott benne (Motta és társai, <i>Archaeometry</i> 59, 2017). A 2015-ös tanulmány szerint ez kevesebb, mint amennyit a korábbi, Frontinus számaiból kiinduló becslések adtak, és már a vékony lerakódás is mintegy 25%-kal csökkentette a legnagyobb hozamot. A hozam csökkenését a szerzők nagyjából Kr. u. 52 és 250 közé teszik.','So the water reaching Rome in the late state of the aqueduct was 1.2–1.4 m³ per second; 1.4 m³/s corresponds to 120,960 ± 34,560 m³ per day. Because of bottlenecks in the channel, more than 2 m³/s could never flow through it (Motta et al., <i>Archaeometry</i> 59, 2017). According to the 2015 study this is less than earlier estimates based on Frontinus\'s figures, and even a thin deposit reduced the maximum flow by about 25%. The authors place the decline in flow roughly between AD 52 and 250.')+'</p>')
    o.append('      <p class="hint">'+T('Frontinus a forrásnál 4738 quinariát mért (<i>De aquaeductu</i> 73). A két adat nem váltható át egymásba: ő keresztmetszetet mért a forrásnál, a travertin a hozamot őrzi három későbbi pontról, ezért a quinariát itt sem számoljuk át köbméterre. A két Tivoli környéki hely a vezeték két párhuzamos ágán van, és más-más időszakot mutat, ezért a három sor nem egyetlen pillanat hossz-szelvénye.','Frontinus measured 4,738 quinariae at the intake (<i>De aquaeductu</i> 73). The two figures cannot be converted into each other: he measured a cross-section at the intake, while the travertine records the flow at three later points, so the quinaria is not converted into cubic metres here either. The two sites near Tivoli lie on two parallel branches of the aqueduct and show different periods, so the three rows are not a profile of a single moment.')+'</p>')
    return '\n'.join(o)+'\n'
SRCLI=lambda l:('      <li><b>Az Anio Novus mért hozama.</b> D. Keenan-Jones, D. Motta, M. H. Garcia, B. W. Fouke: Travertine-based estimates of the amount of water supplied by ancient Rome\'s Anio Novus aqueduct, <i>Journal of Archaeological Science: Reports</i> 3 (2015) 1–10; D. Motta és társai: Hydraulic evaluation of the design and operation of ancient Rome\'s Anio Novus aqueduct, <i>Archaeometry</i> 59 (2017) 1150–1174; D. Keenan-Jones és társai: Travertine crystal growth ripples record the hydraulic history of ancient Rome\'s Anio Novus aqueduct, <i>Scientific Reports</i> 12 (2022) 1239 (CC BY 4.0). A helyszínenkénti értékek a 2022-es cikk S3. kiegészítő táblázatából valók; a 2015-ös és a 2017-es tanulmányból a kivonat és a szerzők későbbi hivatkozásai szerinti számok szerepelnek.</li>' if l=='hu' else '      <li><b>The measured flow of the Anio Novus.</b> D. Keenan-Jones, D. Motta, M. H. Garcia, B. W. Fouke: Travertine-based estimates of the amount of water supplied by ancient Rome\'s Anio Novus aqueduct, <i>Journal of Archaeological Science: Reports</i> 3 (2015) 1–10; D. Motta et al.: Hydraulic evaluation of the design and operation of ancient Rome\'s Anio Novus aqueduct, <i>Archaeometry</i> 59 (2017) 1150–1174; D. Keenan-Jones et al.: Travertine crystal growth ripples record the hydraulic history of ancient Rome\'s Anio Novus aqueduct, <i>Scientific Reports</i> 12 (2022) 1239 (CC BY 4.0). The site-by-site values come from Supplementary Table S3 of the 2022 article; for the 2015 and 2017 studies the figures follow the abstract and the authors\' own later citations.</li>')
